<?php
namespace App\Controllers; use App\Services\{BayerDataService,SimpleXlsxExporter,SimplePdfExporter};
class ExportController {public function index():void{\require_role('ADMIN','GERENCIA','BAYER');\view('exportaciones.index');}
public function count():void{\require_role('ADMIN','GERENCIA','BAYER');$type=(string)\input('type','documents');$rows=(new BayerDataService())->dataset($type);header('Content-Type: application/json; charset=utf-8');echo json_encode(['success'=>true,'count'=>count($rows)]);}
public function export():void{\require_role('ADMIN','GERENCIA','BAYER');$type=(string)\input('type','documents');$format=strtolower((string)\input('format','csv'));$rows=(new BayerDataService())->dataset($type);\audit('exportaciones',$format,null);$base='bayer_'.$type.'_'.date('Ymd_His');if($format==='json'){header('Content-Type: application/json; charset=utf-8');header("Content-Disposition: attachment; filename=$base.json");echo json_encode($rows,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);exit;}if($format==='txt'){header('Content-Type: text/plain; charset=utf-8');header("Content-Disposition: attachment; filename=$base.txt");if($rows){echo implode("\t",array_keys($rows[0]))."\n";foreach($rows as $r)echo implode("\t",array_values($r))."\n";}exit;}if($format==='xlsx'){(new SimpleXlsxExporter())->output($rows,$base.'.xlsx');}if($format==='pdf'){(new SimplePdfExporter())->output($rows,'Bayer - '.ucfirst($type),$base.'.pdf');}$this->csv($rows,$base.'.csv');}private function csv(array $rows,string $f):never{header('Content-Type: text/csv; charset=utf-8');header("Content-Disposition: attachment; filename=$f");$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");if($rows){fputcsv($o,array_keys($rows[0]),';');foreach($rows as $r)fputcsv($o,array_values($r),';');}fclose($o);exit;}}